#include <bits/stdc++.h>
using namespace std;

using ll = long long;

void solve() {
    ll n; cin >> n;
    vector<ll> v(3 * n);
    for(ll i=0; i<3*n; i++) cin >> v[i];
    
    sort(v.begin(), v.end());
    
    vector<ll> x6(3 * n + 1), x4(3 * n + 1), x3(3 * n + 1);
    for(ll i=3 * n - 1; i>=0; i--) {
        x6[i] = x6[i + 1] + v[i] * 6;
        x4[i] = x4[i + 1] + v[i] * 4;
        x3[i] = x3[i + 1] + v[i] * 3;
    }
    
    function<ll(ll, ll)> get4 = [&](ll i, ll j) {
        return x4[i] - x4[j + 1];
    };
    
    function<ll(ll, ll)> get3 = [&](ll i, ll j) {
        return x3[i] - x3[j + 1];
    };
    
    ll base = 0;
    ll ans = 0;
    for(ll i=3*n-1; i>=2*n-1; i--) {
        ll t6 = 3 * n - i - 1;
        // starting for j is i
        
        // cout << t6 << ' ' << base << endl;
        
        function<ll(ll)> get = [&](ll m) {
            ll t3 = n - t6 - m;
            ll curr = get4(i - 2 * m + 1, i) + get3(i - 2 * m - 3 * t3 + 1, i - 2 * m);
            return curr;
        };
        
        ll l = 0, r = n - t6 - 1;
        ll local = base + get4(i - 2 * (r + 1) + 1, i); // all 4s
        
        while(l <= r) {
            ll m = (l + r) >> 1;
            
            ll less = get(m);
            ll more = get(m + 1);
            
            if(less >= more) {
                r = m - 1;
                local = max(local, base + less);
            } else {
                l = m + 1;
                local = max(local, base + more);
            }
        }
        
        ans = max(ans, local);
        
        // cout << t6 << ' ' << ans << endl;
        base += v[i] * 6;
    }
    
    cout << ans << endl;
}

int main() {
	// your code goes here
    ll t; cin >> t;
    while(t--) solve();
}
